import { contextBridge, ipcRenderer } from 'electron'
import { electronAPI } from '@electron-toolkit/preload'

/**
 * Sovereign-Code-specific renderer bridge.
 *
 * W3-T8c: exposes `window.sovereign.getLocalToken()` which the renderer's
 * `authFetch` helper uses to attach `Authorization: Bearer <token>` to
 * service calls. The token is generated by the main process at app boot
 * (see src/main/localToken.ts) and matches what `services/_shared/auth.py`
 * verifies on the server side.
 *
 * W4-T12: exposes `window.sovereign.updater.{getState,check,download,
 * installAndQuit,onStateChange}` which the Settings screen uses to drive
 * the auto-update UI. State changes are pushed via the `updater:state-changed`
 * channel; `onStateChange` returns an unsubscribe function for tidy cleanup.
 */
type UpdaterStateMsg = unknown // structurally validated by the renderer store

const sovereignAPI = {
  getLocalToken(): Promise<string> {
    return ipcRenderer.invoke('local-token:get')
  },
  updater: {
    getState(): Promise<UpdaterStateMsg> {
      return ipcRenderer.invoke('updater:state')
    },
    check(): Promise<UpdaterStateMsg> {
      return ipcRenderer.invoke('updater:check')
    },
    download(): Promise<UpdaterStateMsg> {
      return ipcRenderer.invoke('updater:download')
    },
    installAndQuit(): Promise<UpdaterStateMsg> {
      return ipcRenderer.invoke('updater:install-quit')
    },
    onStateChange(listener: (state: UpdaterStateMsg) => void): () => void {
      const handler = (_event: unknown, state: UpdaterStateMsg) => listener(state)
      ipcRenderer.on('updater:state-changed', handler)
      return () => {
        ipcRenderer.removeListener('updater:state-changed', handler)
      }
    },
  },
}

// Use `exposeInMainWorld` APIs to add methods or properties to `window` object
// These are available to the renderer process and can be used to communicate with the main process.
if (process.contextIsolated) {
  try {
    contextBridge.exposeInMainWorld('electron', electronAPI)
    contextBridge.exposeInMainWorld('sovereign', sovereignAPI)
  } catch (error) {
    console.error(error)
  }
} else {
  // When contextIsolation is disabled (should not happen in production —
  // we set it to true in index.ts — but vitest's jsdom skips preload).
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ;(globalThis as any).sovereign = sovereignAPI
}

export type SovereignAPI = typeof sovereignAPI
